const scrollToEl = el => { if (!el) return; const bar = parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--pt-bar-h')) || 0; const rm = window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches; window.scrollTo({ top: el.getBoundingClientRect().top + window.scrollY - bar - (mo() ? 64 : 80), behavior: rm ? 'auto' : 'smooth' }) };
