const GLOSS = [['Pip', 'The smallest standard price move in a currency pair. For most pairs, 1 pip = 0.0001 (4th decimal place). For JPY pairs, 1 pip = 0.01.'], ['Lot size', 'Standard lot = 100,000 units of base currency. Mini lot = 10,000. Micro lot = 1,000. Determines the monetary value of each pip.'], ['Margin', 'The deposit required to open and maintain a leveraged position. Expressed as a percentage of total position value.'], ['Equity', 'Your account balance plus or minus the floating profit/loss of all open positions.'], ['STP', 'Straight Through Processing. Orders routed directly to liquidity providers without broker intervention. Typically lower conflict of interest.'], ['ECN', 'Electronic Communications Network. Connects traders directly to interbank liquidity. Usually tighter spreads with commission per trade.'], ['Rebate', 'A portion of the spread or commission returned to a trader through an Introducing Broker (IB) or rebate partner like TetherMax.'], ['Stop loss', 'An order to automatically close a position when it reaches a specified loss level. Essential for managing downside risk.'], ['MetaTrader 4 (MT4)', 'A trading platform designed mainly for forex trading. It is lightweight, easy to use, and popular with traders who want a straightforward charting and execution setup. Downloadable via desktop and mobile apps.'], ['MetaTrader 5 (MT5)', 'An advanced multi-market platform that supports forex plus stocks, futures, commodities, and other instruments, with charting tools, and order options. Downloadable via desktop and mobile apps.'], ['Swap (overnight interest)', "A fee charged when you hold a position past the end of the trading day. It's calculated from the interest rate difference between the two currencies, so you can either pay it or earn it. It doesn't apply if you close your position the same day."], ['Margin call', "A warning that fires when your margin starts running low. It's a signal to either add funds or reduce your position."], ['Stop out', 'If your margin keeps falling even after a margin call, the broker automatically closes your remaining positions at this level to keep your losses from growing further.']];
const TOC = [['fx', 'What are FX and CFDs?'], ['price', 'How the Price Works?'], ['lev', 'The Power & Risk of Leverage'], ['gloss', 'Key terms glossary'], ['check', 'Beginner Checklist: Are you ready?']];
