const SH = { nav: 'cashback', moTitle: null };
const NOTE_GNB = 'Figma FX 프레임 헤더는 옛 GNB(Exchanges · Brokers · Events …) — 새 GNB(D4)로 그림. 문구는 실서비스 원문(Figma 오탈자·옛 문구는 실서비스 기준).';
R.screen({ id: 'brokers.main', group: 'cex', title: 'Brokers (FX 소개)', route: '/brokers', fu: [], shell: { ...SH, accent: false },
  states: [{ id: 'normal', label: '기본 — FX 소개 · 앵커 탭 · FAQ', figma: { pc: '28537:492801', mo: '28537:494216' }, note: '[MAX-]FX V2 FX Integration LP · 실서비스 /en/brokers. 허브 Brokers 라우트 행 목적지(정책 RT-2 · REQ-308)' }],
  render() { return landing() + C.note('진입: 허브 Brokers 라우트 행 · 브로커 페이지 간 링크(GNB `Cashback ▾`에는 없음 — D4). `Learn More` · `Read the Basics` → learn, `Compare Brokers` → compare. 앵커 탭 = 그 구역으로 스크롤(PC는 히어로를 지나면 아래 가운데에 뜸, 모바일은 히어로 아래 고정). ' + NOTE_GNB) } });
R.screen({ id: 'brokers.learn', group: 'cex', title: 'Brokers — Learn the Basics', route: '/brokers/learn', fu: [], shell: { ...SH, accent: true },
  states: [{ id: 'normal', label: '기본 — 목차 · 레버리지 · 용어집 · 체크리스트', figma: { pc: '28537:493293', mo: '28537:495560' }, note: '[MAX-]FX V2 Learn · 실서비스 /en/brokers/learn' }],
  render() { return learn() + C.note('오른쪽 목차 = 구역 스크롤 + 현재 구역 표시. `Compare Brokers` → compare. 브레드크럼은 실서비스 `Brokers / Learn the Basics`(Figma `Learn`). ' + NOTE_GNB) } });
R.screen({ id: 'brokers.compare', group: 'cex', title: 'Brokers — Compare Brokers', route: '/brokers/compare', fu: [], shell: { ...SH, accent: false },
  states: [{ id: 'normal', label: '기본 — RS Finance · INFINOX 비교', figma: { pc: '28537:493118', mo: '28537:495361' }, note: '[MAX-]FX V2 Compare 2 brokers · 실서비스 /en/brokers/compare' }],
  render() { return compare() + C.note('`Sign Up ↗` · `Learn More` 둘 다 테더맥스 브로커 상세(실서비스 측정 — 정리안 3장). `Learn the Basics` → learn. ' + NOTE_GNB) } });
R.screen({ id: 'brokers.detail', group: 'cex', title: 'Brokers — 브로커 상세', route: '/brokers/{rs-finance|infinox}', fu: [], shell: { ...SH, accent: true },
  states: [{ id: 'rsFinance', label: 'RS Finance', figma: { pc: '28537:493558', mo: '28537:494735' }, note: '[MAX-]FX V2 RS Finance · 실서비스 /en/brokers/rs-finance' },
    { id: 'infinox', label: 'INFINOX', figma: { pc: '28537:493813', mo: '28537:495010' }, note: '[MAX-]FX V2 INFINOX · 실서비스 /en/brokers/infinox' }],
  render(st) { return detail(st) + C.note('`Select Account` · 1단계 `referral link` · 아래 띠 `Get Started` = Account Type 구역으로 스크롤. 가입(`Sign Up` · INFINOX `Sign Up for STP/ECN Account` · 계정 카드 `Get Started`) = 브로커 가입 사이트 새 탭(실서비스 링크, 계정 유형별 — 라이브 측정). `Compare Brokers` → compare. 단계 점 = 단계 전환. 모바일 Figma `View Website`는 실서비스 `Sign Up`. ' + NOTE_GNB) } });
